mapper.select:
SELECT m.*, s.pre_match_time sell_pre_match_time,s.live_odd_time sell_live_odd_time,s.pre_risk_manager_code sell_pre_risk_manager_code, s.live_risk_manager_code sell_live_risk_manager_code,s.tournament_level sell_tournament_level, s.pre_match_sell_status sell_pre_match_sell_status,s.live_match_sell_status sell_live_match_sell_status, s.label sell_label,s.business_event sell_business_event,s.auditor_id sell_auditor_id, s.auditor sell_auditor, s.live_match_data_provider_code sell_live_match_data_provider_code,s.pre_match_data_provider_code sell_pre_match_data_provider_code, s.pre_trader_id sell_pre_trader_id,s.pre_trader sell_pre_trader,s.live_trader_id sell_live_trader_id,s.live_trader sell_live_trader, s.video_code sell_video_code,s.animation_code sell_animation_code FROM standard_match_info m JOIN standard_sport_market_sell s on s.match_info_id = m.id WHERE 1 = 1
and m.modify_time >= #{beginTime}
and m.modify_time <= #{endTime}
order by m.modify_time, m.id

select t.tournament_level,m.*
from   standard_match_info m,standard_sport_tournament t
where  m.standard_tournament_id = t.id
and    m.data_source_code= #{dataSourceCode}

    and    m.sport_id = #{thirdSportId}

and    m.third_match_source_id = #{thirdMatchSourceId}

select t.tournament_level,m.*
from   standard_match_info m left join standard_sport_tournament t on m.standard_tournament_id = t.id
where  m.id = #{id}

select

from standard_match_info t, market_category_sell m where
t.id = m.match_id and m.market_category_id = #{categoryId, jdbcType=INTEGER} and t.match_over = 0 and t.sport_id = #{sportId, jdbcType=INTEGER}
